 74	export function newMemory(): Memory {
 75	  return { visitedMaps: {}, talked: {}, usedTargets: {}, dialog: [], actions: [], stepsInMap: {}, npcText: {}, lastInteraction: null, intent: null, triedNoProgress: {}, blockedExits: {}, bestHops: {} };
