153	/** Region graph matching current capabilities (rebuilt when Cut/Surf become available). */
154	export function regionGraph(ctx: Ctx): RegionGraph {
155	  const c = capabilities(ctx);
156	  if (c.cut !== ctx.regions.caps.cut || c.surf !== ctx.regions.caps.surf) ctx.regions = new RegionGraph(ctx.rom, c);
157	  return ctx.regions;
158	}
