160	/** Information about under-leveled team members (Jev decides what to do with it). */
161	export function weakTeamNote(ctx: Ctx): string | undefined {
162	  const { m } = currentMilestone(ctx.gs);
163	  const party = ctx.gs.party();
164	  if (!m?.level || !party.length) return undefined;
165	  const weak = party.filter((p) => p.level <= m.level! - 10);
166	  if (!weak.length) return undefined;
167	  return `${weak.length} of your ${party.length} Pokémon are 10+ levels below the typical opponent level of the objective (Lv${m.level}): ${weak.map((p) => `${p.nickname} Lv${p.level}`).join(', ')}. Wild Pokémon at higher levels can be caught and swapped in at a Pokémon Center PC to make the team stronger.`;
168	}
169	
170	const HM_FOR = { CUT: { hm: 'HM01', badge: 0x02, badgeName: 'Cascade Badge' }, SURF: { hm: 'HM03', badge: 0x10, badgeName: 'Soul Badge' } } as const;
171	/** Which party / PC box Pokémon can learn the HM for a field move (from the ROM's compatibility table). */
172	export function fieldMoveLearners(ctx: Ctx, mv: 'CUT' | 'SURF') {
173	  const hmId = [...ctx.rom.items.entries()].find(([, n]) => n === HM_FOR[mv].hm)?.[0];
174	  const can = (speciesId: number) => hmId !== undefined && ctx.rom.canLearnMachine(speciesId, hmId);
175	  // not yet, but after evolving (by level or with an item; trades aren't possible here)
176	  const bag = new Set(ctx.gs.bag().map((i) => i.name));
177	  const viaEvo = (speciesId: number, level?: number): string | undefined => {
178	    for (const e of ctx.rom.evolutions(speciesId)) {
179	      if (e.method === 'trade') continue;
180	      const into = ctx.rom.species.get(e.into)?.name ?? '?';
181	      // level evolutions happen on a level-up: already past the level means its next level-up
182	      const how = e.method === 'level' ? (level !== undefined && level >= e.level! ? `on its next level-up (it's past Lv${e.level})` : `at Lv${e.level}`) : `with a ${ctx.rom.items.get(e.item!) ?? 'item'} (${bag.has(ctx.rom.items.get(e.item!) ?? '') ? 'one is in the bag' : 'none in the bag'})`;
183	      if (can(e.into)) return `evolves into ${into} ${how}, which can learn it`;
184	      const next = viaEvo(e.into, e.method === 'level' ? Math.max(level ?? 0, e.level!) : level);
185	      if (next) return `evolves into ${into} ${how}, then ${next}`;
186	    }
187	    return undefined;
188	  };
189	  const later = (list: { speciesId: number; nickname: string; species: string; level: number }[]) =>
190	    list.filter((p) => !can(p.speciesId)).map((p) => { const v = viaEvo(p.speciesId, p.level); return v ? `${p.nickname} (${p.species} Lv${p.level}) ${v}` : ''; }).filter(Boolean);
191	  const party = ctx.gs.party(), box = ctx.gs.box();
192	  // what each way takes: levels to gain, items to use, PC moves, then teaching the HM (plain counts, no ranking)
193	  const chain = (speciesId: number, depth = 0): { level?: number; item?: string }[] | undefined => {
194	    if (can(speciesId)) return [];
195	    if (depth > 2) return undefined;
196	    for (const e of ctx.rom.evolutions(speciesId)) {
197	      if (e.method === 'trade') continue;
198	      const rest = chain(e.into, depth + 1);
199	      if (rest) return [e.method === 'level' ? { level: e.level } : { item: ctx.rom.items.get(e.item!) ?? '?' }, ...rest];
200	    }
201	    return undefined;
202	  };
203	  const routes: string[] = [];
204	  const costs: { inBox: boolean; cost: number }[] = []; // levels + actions, for the stalled-prerequisite rule
205	  const describe = (m: { speciesId: number; nickname: string; species: string; level: number }, inBox: boolean) => {
206	    const c = chain(m.speciesId);
207	    if (!c) return;
208	    // level evolutions happen on a level-up: one past its evolution level still needs one more level
209	    const lvSteps = c.filter((x) => x.level !== undefined).map((x) => x.level!);
210	    const lv = lvSteps.length ? Math.max(m.level + 1, ...lvSteps) : m.level;
211	    const levels = lv - m.level;
212	    const items = c.filter((x) => x.item).map((x) => x.item!);
213	    if (items.some((i) => !bag.has(i))) return; // an item that isn't in the bag: not a way right now
214	    const parts = [
215	      ...(inBox ? [party.length >= 6 ? 'at a Pokémon Center PC: deposit one team member and withdraw it' : 'at a Pokémon Center PC: withdraw it'] : []),
216	      ...(levels > 0 ? [`gain ${levels} level(s) (Lv${m.level} → Lv${lv})`] : []),
217	      ...items.map((i) => `use the ${i}`),
218	      `teach ${HM_FOR[mv].hm}`,
219	    ];
220	    routes.push(`${m.nickname} (${m.species}, ${inBox ? 'PC box' : 'team'}): ${parts.join(', then ')}`);
221	    costs.push({ inBox, cost: levels + parts.length - (levels > 0 ? 1 : 0) + (inBox && party.length >= 6 ? 1 : 0) });
222	  };
223	  for (const m of party) describe(m, false);
224	  for (const m of box) describe(m, true);
225	  return {
226	    party: party.filter((p) => can(p.speciesId)).map((p) => `${p.nickname} (${p.species} Lv${p.level})`),
227	    box: box.filter((b) => can(b.speciesId)).map((b) => `${b.nickname} (${b.species} Lv${b.level})`),
228	    afterEvolving: [...later(party).map((t) => `in the party: ${t}`), ...later(box).map((t) => `in the PC box: ${t}`)],
229	    routes,
230	    costs,
231	  };
232	}
233	function fieldMoveFact(ctx: Ctx, mv: 'CUT' | 'SURF') {
234	  const h = HM_FOR[mv];
235	  const l = fieldMoveLearners(ctx, mv);
236	  const inBag = ctx.gs.bag().some((i) => i.name === h.hm);
237	  return `The objective can't be reached from here without ${mv}, and no party Pokémon knows ${mv}. ${h.hm} teaches ${mv} (${inBag ? 'it is in the bag; HMs can be used any number of times' : 'not in the bag'}); using ${mv} outside battle needs the ${h.badgeName}${ctx.gs.badges & h.badge ? ' (you have it)' : ' (you don\'t have it yet)'}. Party Pokémon that can learn ${h.hm}: ${l.party.join(', ') || 'none'}. Pokémon in the PC box that can learn it: ${l.box.join(', ') || 'none'}.${l.afterEvolving.length ? ` Able to learn it only after evolving: ${l.afterEvolving.join('; ')}.` : ''}${l.routes.length ? ` What each way takes: ${l.routes.join('; ')}.` : ''}`;
238	}
