 24	
 25	const STATUS = (b: number) =>
 26	  b & 0x07 ? 'SLEEP' : b & 0x08 ? 'POISON' : b & 0x10 ? 'BURN' : b & 0x20 ? 'FREEZE' : b & 0x40 ? 'PARALYZED' : 'OK';
 27	
 28	export class GameState {
 29	  constructor(private emu: Emulator, private rom: Rom) {}
 30	
 31	  get m() { return this.emu.mem; }
 32	  u8(name: string, off = 0) { return this.m[sym(name) + off]; }
 33	  be16(a: number) { return (this.m[a] << 8) | this.m[a + 1]; }
 34	
 35	  get mapId() { return this.u8('wCurMap'); }
 36	  get mapName() { return mapName(this.mapId); }
 37	  get x() { return this.u8('wXCoord'); }
 38	  get y() { return this.u8('wYCoord'); }
 39	  get mapWidth() { return this.u8('wCurMapWidth'); }
 40	  get mapHeight() { return this.u8('wCurMapHeight'); }
 41	  get facing() { return ({ 0: 'down', 4: 'up', 8: 'left', 0xc: 'right' } as Record<number, string>)[this.m[0xc109]] ?? '?'; }
 42	  get inBattle() { return this.u8('wIsInBattle'); } // 0 none, 1 wild, 2 trainer, 0xff lost
 43	  get badges() { return this.u8('wObtainedBadges'); }
 44	  get badgeCount() { let n = 0; for (let b = this.badges; b; b >>= 1) n += b & 1; return n; }
 45	  get walkState() { return this.u8('wWalkBikeSurfState'); } // 0 walk 1 bike 2 surf
 46	  get joyIgnore() { return this.u8('wJoyIgnore'); }
 47	
 48	  get money() {
 49	    const a = sym('wPlayerMoney');
 50	    const bcd = (v: number) => (v >> 4) * 10 + (v & 0xf);
 51	    return bcd(this.m[a]) * 10000 + bcd(this.m[a + 1]) * 100 + bcd(this.m[a + 2]);
 52	  }
 53	
 54	  event(name: string): boolean {
 55	    const bit = EVENTS[name];
 56	    if (bit === undefined) throw new Error(`unknown event ${name}`);
 57	    return !!(this.m[sym('wEventFlags') + (bit >> 3)] & (1 << (bit & 7)));
 58	  }
 59	
 60	  /** Pokédex "owned" flag for a species id (internal index). */
 61	  owned(dex: number): boolean {
 62	    return !!(this.m[sym('wPokedexOwned') + ((dex - 1) >> 3)] & (1 << ((dex - 1) & 7)));
 63	  }
 64	
 65	  get playerName() { return decode(this.m, sym('wPlayerName'), 11); }
 66	
 67	  /** Pokémon in the current PC box (species, nickname, level, types). */
 68	  box(): { speciesId: number; species: string; nickname: string; level: number; types: string[] }[] {
 69	    const n = Math.min(this.u8('wBoxCount'), 20);
 70	    const out = [];
 71	    for (let i = 0; i < n; i++) {
 72	      const a = sym('wBoxMons') + i * 33;
 73	      const sp = this.rom.species.get(this.m[a]);
 74	      out.push({ speciesId: this.m[a], species: sp?.name ?? '?', nickname: decode(this.m, sym('wBoxMonNicks') + i * 11, 11), level: this.m[a + 3], types: sp?.types ?? [] });
 75	    }
 76	    return out;
 77	  }
 78	
 79	  party(): MonState[] {
 80	    const n = Math.min(this.u8('wPartyCount'), 6);
 81	    const out: MonState[] = [];
 82	    for (let i = 0; i < n; i++) {
 83	      const a = sym('wPartyMons') + i * 44;
 84	      const sp = this.rom.species.get(this.m[a]);
 85	      out.push({
 86	        slot: i, speciesId: this.m[a], species: sp?.name ?? '?', nickname: decode(this.m, sym('wPartyMonNicks') + i * 11, 11),
 87	        level: this.m[a + 33], hp: this.be16(a + 1), maxHp: this.be16(a + 34), status: STATUS(this.m[a + 4]),
 88	        types: sp?.types ?? [],
 89	        moves: this.movesAt(a + 8, a + 29),
 90	        stats: { atk: this.be16(a + 36), def: this.be16(a + 38), spd: this.be16(a + 40), spc: this.be16(a + 42) },
 91	      });
 92	    }
 93	    return out;
 94	  }
 95	
 96	  private movesAt(movesAddr: number, ppAddr: number) {
 97	    const out: MonState['moves'] = [];
 98	    for (let j = 0; j < 4; j++) {
 99	      const id = this.m[movesAddr + j];
100	      if (!id) continue;
101	      const mv = this.rom.moves.get(id)!;
102	      const ppByte = this.m[ppAddr + j];
103	      const ups = ppByte >> 6;
104	      out.push({ id, name: mv.name, type: mv.type, power: mv.power, accuracy: mv.accuracy, pp: ppByte & 0x3f, maxPp: mv.pp + Math.floor(mv.pp / 5) * ups });
105	    }
106	    return out;
107	  }
108	
109	  /** Active battlers (only meaningful while inBattle). */
110	  battle() {
111	    const e = sym('wEnemyMon'), p = sym('wBattleMon');
112	    const esp = this.rom.species.get(this.m[e]);
113	    const psp = this.rom.species.get(this.m[p]);
114	    return {
115	      kind: this.inBattle === 1 ? 'wild' : this.inBattle === 2 ? 'trainer' : 'none',
116	      enemy: {
117	        species: esp?.name ?? '?', level: this.m[e + 14], hp: this.be16(e + 1), maxHp: this.be16(e + 15),
118	        status: STATUS(this.m[e + 4]), types: esp?.types ?? [], catchRate: esp?.catchRate ?? 0,
119	      },
120	      enemyPartyCount: this.u8('wEnemyPartyCount'),
121	      player: {
122	        slot: this.u8('wPlayerMonNumber'), species: psp?.name ?? '?', level: this.m[p + 14], hp: this.be16(p + 1), maxHp: this.be16(p + 15),
123	        status: STATUS(this.m[p + 4]), types: psp?.types ?? [], moves: this.movesAt(p + 8, p + 25),
124	      },
125	    };
126	  }
127	
128	  bag(): { id: number; name: string; qty: number }[] {
129	    const n = this.u8('wNumBagItems');
130	    const out = [];
131	    for (let i = 0; i < n && i < 20; i++) {
132	      const a = sym('wBagItems') + i * 2;
133	      out.push({ id: this.m[a], name: this.rom.items.get(this.m[a]) ?? `ITEM_${this.m[a]}`, qty: this.m[a + 1] });
134	    }
135	    return out;
136	  }
137	
138	  /** NPC/object sprites currently on the map (index 1..15). */
139	  sprites(): { index: number; x: number; y: number; hidden: boolean; picture: number }[] {
140	    const out = [];
141	    const n = this.u8('wNumSprites');
142	    const hiddenIdx = new Set<number>();
143	    // wToggleableObjectList: pairs (sprite index, global toggle index) terminated by $FF
144	    for (let a = sym('wToggleableObjectList'); this.m[a] !== 0xff && a < sym('wToggleableObjectList') + 34; a += 2) {
145	      const g = this.m[a + 1];
146	      if (this.m[sym('wToggleableObjectFlags') + (g >> 3)] & (1 << (g & 7))) hiddenIdx.add(this.m[a]);
147	    }
148	    for (let i = 1; i <= n && i < 16; i++) {
149	      const picture = this.m[sym('wSpriteStateData1') + i * 16];
150	      const y = this.m[sym('wSpriteStateData2') + i * 16 + 4] - 4;
151	      const x = this.m[sym('wSpriteStateData2') + i * 16 + 5] - 4;
152	      out.push({ index: i, x, y, hidden: hiddenIdx.has(i) || picture === 0, picture });
153	    }
154	    return out;
155	  }
156	
157	  screen(): ScreenState {
158	    const base = sym('wTileMap');
159	    const rows: string[] = [];
160	    let hasTextBox = false, waitingForA = false, moreBelow = false, nonMapTiles = 0;
161	    let cursor: ScreenState['cursor'] = null;
162	    for (let y = 0; y < 18; y++) {
163	      const tiles = this.m.subarray(base + y * 20, base + y * 20 + 20);
164	      for (let x = 0; x < 20; x++) {
165	        const t = tiles[x];
166	        if (t >= 0x60) nonMapTiles++;
167	        if (t >= 0x79 && t <= 0x7e) hasTextBox = true;
168	        if (t === 0xed) cursor = { x, y };
169	        if (t === 0xee && y >= 12) waitingForA = true;
170	        if (t === 0xee && y < 12) moreBelow = true; // ▼ in the dialog box; a ▼ higher up is a list's 'more below' arrow
171	      }
172	      rows.push(decodeRow(tiles));
173	    }
174	    const dialog = hasTextBox ? [rows[14], rows[16]].map((r) => r.replace(/[┌─┐│└┘]/g, '').trim()).filter(Boolean).join(' ') : '';
175	    return { rows, hasTextBox, nonMapTiles, dialog, waitingForA, moreBelow, cursor };
176	  }
177	
178	  /** Menu registers (cursor-driven menus). */
179	  menu() {
180	    return {
181	      current: this.u8('wCurrentMenuItem'), max: this.u8('wMaxMenuItem'),
182	      topY: this.u8('wTopMenuItemY'), topX: this.u8('wTopMenuItemX'),
183	      watched: this.u8('wMenuWatchedKeys'), listScroll: this.u8('wListScrollOffset'),
184	    };
185	  }
186	}
