    27	
    28	export class GameState {
    29	  constructor(private emu: Emulator, private rom: Rom) {}
    30	
    31	  get m() { return this.emu.mem; }
    32	  u8(name: string, off = 0) { return this.m[sym(name) + off]; }
    33	  be16(a: number) { return (this.m[a] << 8) | this.m[a + 1]; }
    34	
    35	  get mapId() { return this.u8('wCurMap'); }
    36	  get mapName() { return mapName(this.mapId); }
    37	  get x() { return this.u8('wXCoord'); }
    38	  get y() { return this.u8('wYCoord'); }
    39	  get mapWidth() { return this.u8('wCurMapWidth'); }
    40	  get mapHeight() { return this.u8('wCurMapHeight'); }
    41	  get facing() { return ({ 0: 'down', 4: 'up', 8: 'left', 0xc: 'right' } as Record<number, string>)[this.m[0xc109]] ?? '?'; }
    42	  get inBattle() { return this.u8('wIsInBattle'); } // 0 none, 1 wild, 2 trainer, 0xff lost
    43	  get badges() { return this.u8('wObtainedBadges'); }
    44	  get badgeCount() { let n = 0; for (let b = this.badges; b; b >>= 1) n += b & 1; return n; }
    45	  get walkState() { return this.u8('wWalkBikeSurfState'); } // 0 walk 1 bike 2 surf
    46	  get joyIgnore() { return this.u8('wJoyIgnore'); }
    47	
