    66	
    67	  /** Pokémon in the current PC box (species, nickname, level, types). */
    68	  box(): { speciesId: number; species: string; nickname: string; level: number; types: string[] }[] {
    69	    const n = Math.min(this.u8('wBoxCount'), 20);
    70	    const out = [];
    71	    for (let i = 0; i < n; i++) {
    72	      const a = sym('wBoxMons') + i * 33;
    73	      const sp = this.rom.species.get(this.m[a]);
    74	      out.push({ speciesId: this.m[a], species: sp?.name ?? '?', nickname: decode(this.m, sym('wBoxMonNicks') + i * 11, 11), level: this.m[a + 3], types: sp?.types ?? [] });
    75	    }
    76	    return out;
    77	  }
    78	
    79	  party(): MonState[] {
