 598	/** Execute path steps. Stops on map change, text box, battle, or blockage. */
 599	function walk(ctx: Ctx, path: Step[]): WalkResult {
 600	  const { gs, emu } = ctx;
 601	  const map0 = gs.mapId;
 602	  for (const st of path) {
 603	    const x0 = gs.x, y0 = gs.y;
 604	    const btn = st.dir.toUpperCase() as 'UP';
 605	    let moved = false;
 606	    // first press may only turn the player; allow a second attempt
 607	    // generous: with many sprites on screen the game lags and one step can take well over 40 frames
 608	    for (let f = 0; f < 90; f++) {
 609	      emu.frame([btn]);
 610	      if (gs.x !== x0 || gs.y !== y0 || gs.mapId !== map0) { moved = true; break; }
 611	      if (gs.inBattle || gs.screen().hasTextBox) break;
 612	    }
 613	    waitWalkDone(ctx);
 614	    if (st.jump) emu.wait(20);
 615	    if (st.spin) {
 616	      // arrow tile: the game moves the player for us; wait it out, then make sure we landed as predicted
 617	      if (!waitControl(ctx)) return 'interrupted';
 618	      if (gs.mapId !== map0) { settleAfterMapChange(ctx); return 'warped'; }
 619	      if (gs.x !== st.x || gs.y !== st.y) return 'moved'; // landed elsewhere: replan from here
 620	      continue;
 621	    }
 622	    const steps = (ctx.mem.stepsInMap[gs.mapName] ??= new Set());
 623	    steps.add(`${gs.x},${gs.y}`);
 624	    if (gs.mapId !== map0) { settleAfterMapChange(ctx); return 'warped'; }
 625	    if (gs.inBattle || gs.screen().hasTextBox) return 'interrupted';
 626	    // the game took control of the player: a trainer walking over, or an arrow tile sliding us along
 627	    if (!moved && ((gs.joyIgnore & 0xf0) || (gs.u8('wStatusFlags5') & 0x80))) {
 628	      if (!waitControl(ctx)) return 'interrupted';
 629	      if (gs.inBattle || gs.screen().hasTextBox || gs.u8('wCurOpponent')) return 'interrupted';
 630	      if (gs.mapId !== map0) { settleAfterMapChange(ctx); return 'warped'; }
 631	      return 'moved'; // silently moved somewhere else: replan
 632	    }
 633	    if (!moved) return 'blocked';
 634	  }
 635	  return 'ok';
 636	}
