 638	function face(ctx: Ctx, tx: number, ty: number) {
 639	  const dx = Math.sign(tx - ctx.gs.x), dy = Math.sign(ty - ctx.gs.y);
 640	  const d = dx > 0 ? 'RIGHT' : dx < 0 ? 'LEFT' : dy > 0 ? 'DOWN' : 'UP';
 641	  const want = { DOWN: 0, UP: 4, LEFT: 8, RIGHT: 0xc }[d];
 642	  const facing = () => ctx.emu.mem[sym('wSpritePlayerStateData1FacingDirection')];
 643	  // a tap right after a walk can be dropped; retry until the player actually faces the target
 644	  for (let i = 0; i < 4 && (i === 0 || facing() !== want); i++) {
 645	    waitWalkDone(ctx);
 646	    ctx.emu.press(d, 3, 6);
 647	  }
 648	}
