 650	export async function execute(ctx: Ctx, c: Candidate, agent: Agent): Promise<WalkResult | undefined> {
 651	  const { gs, emu } = ctx;
 652	  const t = c.target;
 653	  let res = walk(ctx, c.path);
 654	  // replan to the same target from wherever we ended up: someone stepped in the way (once),
 655	  // or arrow tiles etc. slid us somewhere (keep going)
 656	  let blockedRetries = 1;
 657	  for (let i = 0; i < 12 && (res === 'moved' || (res === 'blocked' && blockedRetries-- > 0)); i++) {
 658	    if (res === 'blocked') emu.wait(20);
 659	    const again = buildCandidates(ctx).find((k) => k.key === c.key);
 660	    if (!again) break;
 661	    res = walk(ctx, again.path);
 662	  }
 663	  if (res === 'moved') return res;
 664	  if (res === 'interrupted') { pendingTarget = { map: gs.mapId, key: c.key, resumes: resumingCount + 1 }; return res; }
 665	  if (res !== 'ok') return res;
 666	  switch (t.kind) {
 667	    case 'warp': {
 668	      emu.wait(20);
 669	      // carpet/edge warps need a push toward the edge
 670	      const map0 = gs.mapId;
 671	      const last = c.path[c.path.length - 1]?.dir;
 672	      for (const d of [last, 'down', 'up', 'left', 'right'].filter(Boolean) as Dir[]) {
 673	        emu.hold(d.toUpperCase() as 'UP', 16);
 674	        emu.wait(20);
 675	        if (gs.mapId !== map0 || gs.screen().hasTextBox) break;
 676	      }
 677	      return;
 678	    }
 679	    case 'npc': {
 680	      const sp = gs.sprites().find((s) => s.index === t.index);
 681	      const tx = sp?.x ?? t.x, ty = sp?.y ?? t.y;
 682	      ctx.mem.lastInteraction = `${gs.mapName}:npc${t.index}`;
 683	      ctx.mem.currentTalk = [];
 684	      ctx.mem.talked[ctx.mem.lastInteraction] = (ctx.mem.talked[ctx.mem.lastInteraction] ?? 0) + 1;
 685	      face(ctx, tx, ty);
 686	      tap(ctx, 'A', 20);
 687	      return;
 688	    }
 689	    case 'sign': {
