 46	function effWord(e: number) {
 47	  return e === 0 ? 'NO effect (immune)' : e >= 4 ? 'super effective x4' : e >= 2 ? 'super effective x2' : e <= 0.25 ? 'not very effective x0.25' : e < 1 ? 'not very effective x0.5' : 'normal effectiveness';
 48	}
