 18	  // Only type if the name field is empty (otherwise accept what's there). The field is row 2 from column 10
 19	  // on both the player/rival and the nickname screens (naming_screen.asm).
 20	  const typed = (rows()[2] ?? '').slice(10).trim();
 21	  if (typed.replace(/[_\s]/g, '')) { tap(ctx, 'START', 20); return; }
 22	  for (const ch of name) {
 23	    for (let i = 0; i < 20; i++) {
 24	      const s = ctx.gs.screen();
 25	      let pos: { x: number; y: number } | null = null;
 26	      for (let y = 4; y < 16 && !pos; y++) {
 27	        for (let x = 0; x < 20; x++) if (s.rows[y][x] === ch && (x === 0 || s.rows[y][x - 1] !== ch)) { pos = { x, y }; break; }
 28	      }
 29	      const cur = s.cursor;
 30	      if (!pos || !cur) break;
 31	      if (cur.y === pos.y && cur.x === pos.x - 1) { tap(ctx, 'A', 8); break; }
 32	      if (cur.y > pos.y) tap(ctx, 'UP', 6);
 33	      else if (cur.y < pos.y) tap(ctx, 'DOWN', 6);
 34	      else if (cur.x > pos.x - 1) tap(ctx, 'LEFT', 6);
 35	      else tap(ctx, 'RIGHT', 6);
