391	/** Press A and verify the screen reacted; retry a few times (some menus drop early presses). */
392	export function confirmA(ctx: Ctx, tries = 3): boolean {
393	  for (let i = 0; i < tries; i++) {
394	    const before = ctx.gs.screen().rows.join('') + JSON.stringify(ctx.gs.screen().cursor);
395	    tap(ctx, 'A', 4);
396	    for (let f = 0; f < 40; f++) {
397	      const now = ctx.gs.screen().rows.join('') + JSON.stringify(ctx.gs.screen().cursor);
398	      if (now !== before || ctx.gs.inBattle === 0 && f > 30) { ctx.emu.wait(4); return true; }
399	      ctx.emu.frame();
400	    }
401	  }
402	  return false;
403	}
