405	/** Wait until the tilemap differs from `before` (menu closed / next screen drawn). */
406	export function waitForChange(ctx: Ctx, before: string, maxFrames: number) {
407	  for (let i = 0; i < maxFrames; i++) {
408	    if (ctx.gs.screen().rows.join('') !== before) { ctx.emu.wait(4); return; }
409	    ctx.emu.frame();
410	  }
411	}

